mapper.sql:
LEFT JOIN lab_project p ON p.id = t.project_id
LEFT JOIN lab_project_member current_member
    ON current_member.project_id = t.project_id AND current_member.user_id = #{userId}

mapper.select:
SELECT FROM lab_experiment_template t
LEFT JOIN sys_user creator ON creator.id = t.created_by WHERE 1 = 1
ORDER BY ${sortColumn} ${sortOrder}, t.id DESC LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE lab_experiment_template
SET title = #{title}, description = #{description}, category = #{category}, update_time = #{now}
WHERE id = #{templateId}
